from roz_native_content import COURSES, S

COURSES[5] = [
S('Shlukování a segmentace', (1,2), 'Rozpoznávání obrazců V · Michal Haindl · podklady 2023–2024.|Shlukování hledá skupiny v příznakovém prostoru. Segmentace navíc pracuje s prostorovým rozdělením obrazu. Projdeme předzpracování, vzdálenosti, hierarchie, rozklady a jejich hodnocení.', diagram='pipeline'),
S('Kdy oblasti tvoří segmentaci', (3,10), 'Oblasti mají pokrýt celou sledovanou doménu a navzájem se nepřekrývat. Každá splňuje zvolené kritérium homogenity; dvě sousední oblasti už společně toto kritérium splňovat nemají.|Požadavek souvislosti je prostorový. Shluk v příznacích může obsahovat body z několika vzdálených míst obrazu. Směs hustot je statistický model, nikoli automaticky prostorová segmentace.', [r'\bigcup_{k=1}^{K}R_k=\Omega',r'R_i\cap R_j=\varnothing\quad(i\ne j)'], diagram='regions'),
S('Kolik existuje rozkladů', (11,11), 'Počet rozkladů n objektů do K neprázdných neoznačených skupin udávají Stirlingova čísla druhého druhu. Již pro 15 objektů a tři skupiny existuje 2 375 101 možností.|Úplné prohledávání proto rychle přestává být použitelné. Volba algoritmu znamená také volbu omezení a preferované struktury.', [r'S(n,K)=\frac1{K!}\sum_{j=0}^{K}(-1)^{K-j}\binom Kj j^n']),
S('Sousednost a souvislost', (12,14), 'Čtyřsousednost spojuje pixely přes společnou stranu, osmisousednost i přes roh. Cesta je posloupnost sousedních pixelů splňujících požadovanou podobnost.|Smíšená sousednost připouští diagonálu jen tehdy, pokud společný čtyřsoused nepřináší jinou přípustnou cestu. Volbu sousednosti uvádíme společně s výsledkem.', comment='Dva dotýkající se rohy jsou jedna komponenta v osmisousednosti a dvě ve čtyřsousednosti. Nejde o chybu algoritmu, ale o odlišnou definici spojení.', diagram='connectivity'),
S('Odlehlé hodnoty a chybějící data', (15,18), 'Odlehlost posuzujeme v kontextu modelu. Pravidlo tří směrodatných odchylek je pomůcka pro přibližně normální jednorozměrná data, ne obecná definice chyby.|Chybějící hodnoty lze imputovat, předvídat nebo vynechat v definici vzdálenosti. Každý postup mění informaci a může zavést systematické zkreslení. Imputaci učíme pouze z trénovací části.'),
S('Normalizace mění geometrii', (19,26), 'Centrovat můžeme každý objekt nebo jednotlivé příznaky. Tyto operace řeší různé problémy. U z-skóre standardizujeme každý příznak jeho trénovacím průměrem a odchylkou.|Min–max převod používá rozsah příznaku. Konstantní příznak vyžaduje zvláštní zacházení, protože jmenovatel je nulový. Nové minimum a maximum neodhadujeme z testu.', [r'z_{ij}=\frac{x_{ij}-\mu_j}{s_j}',r'u_{ij}=\frac{x_{ij}-a_j}{b_j-a_j}'], comment='Eukleidovská vzdálenost standardizaci nevyžaduje jako matematickou podmínku. Standardizace je věcná volba: určuje relativní váhu jednotek a rozptylů.', diagram='affine'),
S('Více kanálů a rodiny metod', (27,29), 'Multispektrální pixel má více souřadnic. Můžeme klasifikovat společný vektor nebo spojit dílčí tematické mapy; druhý postup může ztratit závislosti mezi kanály.|K dispozici je prahování, shlukování, růst oblastí, dělení a slučování nebo hledání nespojitostí. Rozhoduje reprezentace i využití kontextu.'),
S('Prahování a histogram', (30,32), 'Globální práh je společný pro celý obraz, lokální se mění s okolím. Pásmové prahování vymezuje interval hodnot.|Histogram neobsahuje rozmístění pixelů. Je odolný vůči jejich přeuspořádání právě proto, že tuto informaci zahazuje. Stejný histogram mohou mít velmi rozdílné obrazy.', [r'\widehat y(x)=\begin{cases}1&x>T\\0&x\le T\end{cases}']),
S('Bayesovsky zvolený práh', (33,34), 'Pro dvě třídy a ztrátu 0–1 leží rozhodovací přechod tam, kde se rovnají vážené hustoty. Různé rozptyly mohou vést ke dvěma přechodům, takže jediný práh nemusí stačit.|Při společném rozptylu a μ₁<μ₂ dostaneme následující práh. Parametry i apriorní pravděpodobnosti je potřeba odhadnout nebo věcně určit.', [r'\pi_1p_1(T)=\pi_2p_2(T)',r'T=\frac{\mu_1+\mu_2}{2}+\frac{\sigma^2}{\mu_2-\mu_1}\log\frac{\pi_1}{\pi_2}'], diagram='gaussian'),
S('Tvar shluku je součást předpokladu', (35,45), 'Kompaktní kulové shluky, protáhlé útvary, soustředné prstence a nestejně velké skupiny vyžadují odlišné představy o podobnosti.|Algoritmus vytvoří rozdělení i v datech bez věcných tříd. Výstup není sám o sobě důkazem, že objevil přirozené kategorie.', diagram='clusters'),
S('Typ příznaku a jeho kód', (46,48), 'Nominální hodnoty nemají pořadí: číselný kód kategorie není vzdálenost. One-hot kódování odděluje jednotlivé možnosti.|Ordinální hodnoty mají pořadí, ale ne nutně stejné odstupy. Teplota ve stupních Celsia je intervalová; poměrová veličina má navíc věcně smysluplnou nulu. Kódování má tato rozlišení respektovat.'),
S('Co musí splňovat metrika', (49,51), 'Metrika je nezáporná, symetrická, nulová právě pro shodné body a splňuje trojúhelníkovou nerovnost. Minkowského rodina zahrnuje Manhattan, Eukleid a maximum souřadnicových rozdílů.|Mahalanobisova metrika používá pozitivně definitní kovarianci. Kvadratická forma bez odmocniny obecně metrikou není.', [r'd_p(x,y)=\left(\sum_j|x_j-y_j|^p\right)^{1/p}',r'p\ge1',r'd_M(x,y)=\sqrt{(x-y)^\top\Sigma^{-1}(x-y)}'], comment='Redakční upřesnění: logaritmus libovolné metriky nemusí být metrika. Také Manhattanova a šachovnicová vzdálenost jsou různé případy (p=1 a p→∞).'),
S('Podobnosti pro různá data', (52,56), 'Korelační nepodobnost 1−ρ není obecně metrikou. U binárních dat rozlišujeme společné jedničky, společné nuly a neshody. Zda společné nuly znamenají shodu, záleží na významu dat.|Jaccardova podobnost ignoruje společné nuly; prostá shoda je započítá. U prázdných jmenovatelů musíme stanovit konvenci. Smíšená data lze spojit váženým součtem vhodně škálovaných dílčích vzdáleností.', [r'J=\frac{a}{a+b+c}',r'M=\frac{a+d}{a+b+c+d}'], comment='Pro příklad podkladu a=3, b=3, c=2, d=2 je prostá shoda 0,5 a Jaccardova podobnost 0,375. Nezaměňujme obě čísla.'),
S('Hierarchické slučování', (57,64), 'Začneme jednotlivými objekty, vybereme nejbližší dvojici shluků a sloučíme ji. Aktualizujeme vzdálenosti a pokračujeme do požadované úrovně.|Dendrogram zachovává posloupnost sloučení. Jednou spojené objekty se při aglomeraci už nerozdělí; řez stromem určuje konečný počet shluků.', diagram='dendrogram'),
S('Co znamená vzdálenost shluků', (65,70), 'Single linkage bere nejbližší dvojici bodů, complete linkage nejvzdálenější. Průměrové varianty rozlišují stejné váhy objektů a stejné váhy celých shluků.|Wardova metoda minimalizuje nárůst vnitroshlukové sumy čtverců. Volba vazby může změnit celý strom. V příkladu vzdáleností 12 a 6 dostane single link 6, complete link 12.', [r'd_{single}(A,B)=\min_{x\in A,y\in B}d(x,y)',r'd_{complete}(A,B)=\max_{x\in A,y\in B}d(x,y)']),
S('K-means: dvě střídající se úlohy', (71,74), 'Při daných středech přiřadíme každý bod nejbližšímu. Při daném přiřazení nahradíme každý střed průměrem jeho skupiny. Oba kroky nezvyšují zvolené optimalizační kritérium.|Ve standardní verzi minimalizujeme sumu čtverců vzdáleností. Výsledek závisí na inicializaci; prázdný shluk vyžaduje explicitní pravidlo. Loket křivky je pomůcka pro K, nikoli důkaz správného počtu.', [r'J=\sum_i\min_k\|x_i-\mu_k\|^2'], diagram='kmeans'),
S('Heuristiky a affinity propagation', (75,79), 'Sekvenční heuristika vytvoří nový shluk, když se bod nevejde do existujících. Je rychlá, ale závisí na pořadí a prahu.|Affinity propagation posílá odpovědnosti a dostupnosti mezi kandidátními reprezentanty. O exempláři rozhoduje součet zpráv; preference na diagonále ovlivňuje počet shluků. Není tedy bez parametrů.', [r'M_{ik}=\max_{j\ne k}\{a(i,j)+s(i,j)\}',r'r(i,k)=s(i,k)-M_{ik}']),
S('Jak ověřit nalezené shluky', (80,87), 'Externí validace porovnává s referenčním označením, interní hodnotí strukturu samotných dat a relativní porovnává varianty. Referenční nulový model pomáhá odlišit strukturu od artefaktu.|Calinskiho–Harabaszův index poměřuje mezishlukový a vnitroshlukový rozptyl. Randův index počítá shodu dvojic; samotná vysoká shoda může být ovlivněna převahou oddělených dvojic.', [r'CH=\frac{\operatorname{tr}(S_B)/(K-1)}{\operatorname{tr}(S_W)/(n-K)}',r'RI=\frac{a+d}{\binom n2}']),
S('Rozptylové matice', (88,89), 'Celkový rozptyl lze rozdělit na vnitroshlukovou a mezishlukovou část. Stopy a determinanty popisují odlišné vlastnosti: celkovou energii a objem.|Kritéria s inverzí vyžadují nesingularitu. Prostá stopa vnitroshlukové matice není invariantní k libovolnému přeskálování souřadnic.', [r'S_T=S_W+S_B',r'S_W=\sum_k\sum_{x\in R_k}(x-\mu_k)(x-\mu_k)^\top']),
S('Růst, dělení a slučování oblastí', (90,94), 'Růst oblastí využívá semena, sousednost a kritérium přijetí pixelu. Záleží na volbě semen, pořadí i pravidle ukončení.|Split-and-merge rozdělí nehomogenní oblast a poté slučuje přípustné sousední oblasti. Čtyřstrom organizuje dělení, ale výsledné hranice nesmějí být jen artefaktem čtvercové sítě.', diagram='regions'),
S('Segmentace pohybu', (95,95), 'Rozdíl dvou registrovaných snímků zvýrazní změnu intenzity. Aby vypovídal o pohybu, potřebujeme zohlednit osvětlení, šum a pohyb kamery.|Pozadí odhadnuté z více snímků je stabilnější než jediná reference. Změna obrazu není automaticky pohyb konkrétního objektu.', [r'D_t(r)=\mathbf1\{|I_t(r)-B(r)|>T\}'])
]

COURSES[6] = [
S('Výběr a extrakce příznaků', (1,2), 'Rozpoznávání obrazců VI · Michal Haindl · podklady 2023–2024.|Budeme hledat menší a užitečnější reprezentaci: nejprve výběrem měření, potom transformací souřadnic. Kritérium kvality musí odpovídat cíli.', diagram='projection'),
S('Výběr není totéž co transformace', (3,10), 'Výběr ponechá podmnožinu původních příznaků. Extrakce vytváří nové souřadnice jako funkce vstupu; ani použití všech vstupů nezaručuje zachování veškeré informace.|Motivací je cena měření, přenos, interpretovatelnost, stabilnější odhad i klasifikace. Nejlepší komprese pro rekonstrukci nemusí být nejlepší pro rozlišení tříd.', [r'z=x_J\quad\text{(výběr)}',r'z=f(x)\quad\text{(extrakce)}']),
S('Filter, wrapper a embedded', (11,16), 'Filter hodnotí data bez trénování konkrétního finálního klasifikátoru. Wrapper hodnotí podmnožinu pomocí klasifikátoru a validačního protokolu. Embedded metoda zahrnuje výběr do učení.|Hybrid kombinuje rychlý předvýběr a dražší posouzení interakcí. Validační dělení musí obepínat i výběr příznaků.', comment='Při reportování výkonu wrapperu použij vnější test nebo vnořenou validaci. Ta samá validační data nesmějí zároveň rozhodnout o výběru a nezávisle potvrdit jeho výkon.', diagram='pipeline'),
S('Proč může méně příznaků pomoci', (17,20), 'Ideální Bayesovo rozhodnutí může další příznak ignorovat; jeho optimální riziko proto přidáním informace nevzroste. Naučený konečný model má ale chybu odhadu, numerické chyby i omezenou kapacitu.|Výběr může napravit nevhodný model a zmenšit rozptyl. Přitom zavádí vlastní chybu hledání a riziko přeučení na hodnoticí kritérium.', diagram='bias-variance'),
S('Oddělení hustot a Bayesova chyba', (21,24), 'Pro dvě třídy závisí minimální chyba na překryvu vážených hustot. Vzdálenost rozdělení může poskytnout náhradní kritérium nebo mez chyby.|f-divergence používá konvexní funkci poměru hustot. Ne každá divergence je symetrická a ne každá splňuje axiomy metriky.', [r'P_e=\int\min\{\pi_1p_1(x),\pi_2p_2(x)\}\,dx',r'D_f(p\|q)=\int q(x)f(\frac{p(x)}{q(x)})\,dx']),
S('Rodiny pravděpodobnostních vzdáleností', (25,26), 'Chernoffova rodina mění exponent s mezi 0 a 1. Bhattacharyyova vzdálenost odpovídá s=1/2. Matusitova vzdálenost porovnává odmocniny hustot.|Symetrizovaná KL divergence porovnává logaritmický poměr, Patrickova–Fisherova míra rozdíl hustot v L². Vážené varianty navíc zohledňují apriorní četnosti.', [r'B=-\log\int\sqrt{p_1p_2}\,dx',r'M^2=\int(\sqrt{p_1}-\sqrt{p_2})^2dx',r'D=\int(p_1-p_2)\log(p_1/p_2)\,dx']),
S('Gaussovské třídy', (27,29), 'U normálních rozdělení se vzdálenosti vyjádří pomocí středů a kovariancí. Rozdíl středů i rozdíl tvarů hustot mohou nést informaci.|Při společné kovarianci je Bhattacharyyova vzdálenost osminou kvadratické Mahalanobisovy vzdálenosti středů. Součet párových kritérií u více tříd je už náhradní vícetřídé kritérium.', [r'\Sigma_1=\Sigma_2=\Sigma\quad\Longrightarrow',r'B=\tfrac18(\mu_1-\mu_2)^\top\Sigma^{-1}(\mu_1-\mu_2)'], diagram='gaussian'),
S('Závislost, entropie a rozptyl', (30,38), 'Pokud se podmíněné rozdělení příznaků neliší mezi třídami, pozorování o třídě neinformuje. Můžeme měřit odchylku podmíněné hustoty od celkové nebo pokles nejistoty.|Podmíněná Shannonova entropie průměruje nejistotu posterioru. Rozptylová kritéria poměřují vzdálenost tříd s jejich vnitřní variabilitou; sama neznají celý tvar hustot.', [r'h(x)=-\sum_kP(k\mid x)\log_2P(k\mid x)',r'H(Y\mid X)=E_X[h(X)]',r'J=\operatorname{tr}(S_W^{-1}S_B)']),
S('Kombinatorická cena výběru', (39,41), 'Výběr m z d příznaků obsahuje binomický počet kandidátů. Řazení jednotlivých příznaků obecně neřeší interakce ani redundanci.|Výjimkou je skutečně aditivní kritérium, například vhodná Gaussovská úloha se společnou diagonální kovariancí. Pak lze seřadit jednotlivé příspěvky.', [r'\#J=\binom dm',r'D^2=\sum_{j\in J}\frac{(\mu_{1j}-\mu_{2j})^2}{\sigma_j^2}']),
S('Odstranění korelovaných měření', (42,47), 'Metoda vzájemných korelací opakovaně odstraní příznak s největší průměrnou absolutní korelací k ostatním. Po každém odstranění se skóre aktualizuje.|Malá korelace není obecně nezávislost a velká korelace neznamená zbytečnost pro klasifikaci. Tato heuristika hledá nízkou lineární redundanci, nikoli automaticky nejlepší třídy.'),
S('Branch-and-bound', (48,52), 'Strom organizuje postupné odstraňování příznaků. Máme-li platnou horní mez dosažitelného skóre celé větve a ta už nepřekoná dosavadní řešení, větev vynecháme.|Monotónní kritérium takovou mez umožňuje. Optimálnost platí pouze při správné mezi a úplném dovoleném prohledání; počet navštívených uzlů může být stále velký.', [r'J(A)\le J(B)\quad\text{pro }A\subseteq B'], diagram='tree'),
S('Sekvenční a náhodné hledání', (53,58), 'Dopředný výběr přidává nejlepší zbývající příznak, zpětný odebírá nejméně škodlivý. Nevratná rozhodnutí vytvářejí vnořené podmnožiny a mohou minout optimum.|Simulované žíhání někdy přijme horší řešení. Genetické hledání pracuje s populací bitových masek. Obě metody vyžadují rozpočet i nezávislé ověření výsledku.', [r'P(\text{přijetí})=\min\{1,e^{-\Delta E/T}\}']),
S('Lineární extrakce', (59,62), 'Při z=Aᵀx se střed transformuje jako Aᵀμ a kovariance jako AᵀΣA. Optimalizovat lze přímo kritérium oddělení tříd.|U dvou tříd se společnou kovariancí je Fisherův směr úměrný Σ⁻¹(μ₁−μ₂). Nelineární extrakce umožní složitější reprezentace, ale komplikuje odhad i interpretaci.', [r'\mu_z=A^\top\mu',r'\Sigma_z=A^\top\Sigma A']),
S('PCA a Karhunenova–Loèvova reprezentace', (63,74), 'Po centrování zvolíme vlastní vektory kovariance podle klesajících vlastních čísel. Projekce do prvních m směrů minimalizuje střední kvadratickou chybu lineární rekonstrukce.|Chyba je součet vynechaných vlastních čísel. Nové souřadnice jsou nekorelované; nezávislé jsou obecně až za dalších předpokladů, například společné normality.', [r'\Sigma u_j=\lambda_j u_j',r'z=U_m^\top(x-\mu)',r'E\|x-\widehat x\|^2=\sum_{j>m}\lambda_j'], comment='Velký rozptyl neznamená velkou diskriminační informaci. Rozlišující příznak může mít malý rozptyl. Optimálnost PCA se týká rekonstrukčního kritéria, nikoli každého informačního cíle.', diagram='projection'),
S('LDA využívá označení tříd', (75,75), 'Lineární diskriminační analýza hledá směry s velkým mezitřídním a malým vnitrotřídním rozptylem. Jde o jinou úlohu než zachování celkového rozptylu.|Počet nezávislých diskriminačních směrů je nejvýše K−1. Singularitu vnitrotřídní matice řešíme redukcí nebo regularizací.', [r'S_Bu=\lambda S_Wu']),
S('Sammonovo zobrazení', (76,78), 'Sammonova projekce numericky hledá nízkorozměrné pozice, které zachovají původní párové vzdálenosti, se zvýšeným důrazem na malé vzdálenosti.|Výsledkem je poloha konkrétních bodů. Pro nový bod potřebujeme další postup, nikoli jen tabulku souřadnic. Nulové vzdálenosti duplicitních bodů vyžadují ošetření.', [r'E=\frac1{\sum_{i<j}d^*_{ij}}\sum_{i<j}\frac{(d^*_{ij}-d_{ij})^2}{d^*_{ij}}'])
]

COURSES[7] = [
S('Jak hodnotit klasifikaci', (1,2), 'Rozpoznávání obrazců VII · Michal Haindl · podklady 2023–2024.|Od úpravy tematické mapy přejdeme k matici záměn, chybám, validačním protokolům a párovému porovnávání klasifikátorů.', diagram='pipeline'),
S('Vyhlazení tematické mapy', (3,7), 'Většinový filtr nahrazuje označení v okolí nejčastější třídou. Může odstranit izolovaný šum, ale také malé skutečné objekty a přesunout hranice.|Medián číselných kódů nominálních tříd nemá obecně věcný význam. Filtrování příznaků před klasifikací a filtrování hotových tříd jsou různé operace.', comment='Vyšší vizuální homogenita není automaticky nižší chyba. Změnu ověř na nezávislé referenci včetně malých objektů a hranic.', diagram='regions'),
S('Výkon závisí na úloze', (8,14), 'Subjektivní prohlídka pomůže odhalit artefakty. Objektivní vyhodnocení potřebuje definovanou referenci, výběr testu, jednotku pozorování a ztrátovou funkci.|Neexistuje univerzálně nejlepší klasifikátor pro všechny možné úlohy. Bayesova chyba je vlastnost rozdělení a ztráty; empirická testová chyba ji pouze odhaduje za daného protokolu.', [r'P_e^*=1-\int\max_k\{\pi_kp(x\mid k)\}\,dx']),
S('Test má odpovídat nasazení', (15,18), 'Reprezentativní test zachycuje cílovou populaci i obtížné případy. Výběr jen nejodlišnějších vzorků změní jeho rozdělení.|U obrazu nerozděluj těsně sousedící nebo odvozené výřezy náhodně mezi trénink a test, pokud sdílejí informaci. Označení chyb I/II v různých oborech kolísá; vždy popiš skutečnou a predikovanou událost.'),
S('Matice záměn s jasnými osami', (19,23), 'V této webové verzi jsou řádky skutečné třídy a sloupce predikované. Diagonála obsahuje správná rozhodnutí.|Pro zvolenou třídu se všechny ostatní třídy sloučí do negativní skupiny. TP je správně pozitivní, FN přehlédnuté pozitivní, FP falešně pozitivní a TN správně negativní.', diagram='confusion'),
S('Přesnost, úplnost a průnik', (24,28), 'Precision odpovídá na otázku, kolik pozitivních předpovědí bylo správných. Recall říká, kolik skutečně pozitivních případů jsme našli. IoU porovnává průnik se sjednocením.|Změna rozhodovacího prahu vytváří precision–recall křivku. Plochu i zvolený pracovní bod reportujeme spolu s četností pozitivní třídy. Při nulovém jmenovateli je metrika bez stanovené konvence nedefinovaná.', [r'\mathrm{precision}=\frac{TP}{TP+FP}',r'\mathrm{recall}=\frac{TP}{TP+FN}',r'\mathrm{IoU}=\frac{TP}{TP+FP+FN}']),
S('Náklady chyb a nevyvážené třídy', (29,31), 'Stejná četnost různých chyb nemusí znamenat stejné riziko. Ztrátu lze průměrovat podle skutečných důsledků rozhodnutí.|V podkladu je 998 jablek a dvě hrušky. Klasifikátor „vždy jablko“ má accuracy 99,8 %, ale nulový recall hrušek. Převzorkování tréninku nemění samo o sobě cílové četnosti.', [r'\widehat R=\frac1n\sum_iL(\widehat y_i,y_i)']),
S('Segmentace vyžaduje i hodnocení oblastí', (32,37), 'Pixelové skóre neodhalí každé rozdělení jednoho objektu ani spojení několika objektů. Oblastní hodnocení rozlišuje správnou detekci, nadsegmentaci, podsegmentaci, vynechané oblasti a šum.|V ukázce ALI-kNN se porovnávají průniky referenčních a nalezených oblastí při zvoleném prahu 0,75. Procenta podkladu patří konkrétnímu experimentu, nikoli obecnému výkonu metody.'),
S('Resubstituce a hold-out', (38,39), 'Resubstituce hodnotí model na stejných případech, na kterých se učil. Obvykle podhodnocuje budoucí chybu.|Hold-out oddělí testovací množinu, ale výsledek závisí na dělení a velikosti testu. Ladění parametrů má vlastní validační část; test nevybírá vítěznou konfiguraci.', diagram='split'),
S('Křížová validace a bootstrap', (40,46), 'V k-fold validaci se model opakovaně učí bez právě hodnoceného bloku. Trénovací části se překrývají, takže jednotlivé odhady nejsou nezávislé replikace.|Bootstrap vzorkuje s opakováním. Pravděpodobnost, že případ v n tazích nebude vybrán, míří k 1/e. Out-of-bag případy slouží k hodnocení, ale neřeší automaticky ladění ani závislé vzorky.', [r'P(\text{OOB})=(1-1/n)^n\longrightarrow e^{-1}',r'\widehat E_{CV}=\frac1n\sum_iL(\widehat y_i^{(-fold(i))},y_i)'], comment='I normalizaci, imputaci a výběr příznaků přepočítej uvnitř trénovacího foldu. Historické rotační a Toussaintovy odhady kombinují dělení a resubstituci; nejsou univerzálně nezaujaté.'),
S('Historický příklad LANDSAT', (47,49), 'Podklad porovnává odhady chyby na multispektrálních datech LANDSAT se sedmi třídami. U téhož Bayesova klasifikátoru uvádí resubstituci 27,6 %, hold-out 33,9 %, rotaci 30,4 % a Toussaintův odhad 28,9 %.|Čísla ukazují závislost závěru na protokolu. Nejsou novým měřením GRAFIT ani srovnáním dnešních algoritmů.', table=[['Odhad','Chyba v podkladu'],['Resubstituce','27,6 %'],['Hold-out','33,9 %'],['Rotace','30,4 %'],['Toussaint','28,9 %']]),
S('Proč nestačí celková accuracy', (50,56), 'Další příklad LANDSAT TM rozlišuje 15 tříd v sedmi pásmech. Záměna jetele a trávy nebo městské třídy může zůstat skryta v průměru.|Uváděná accuracy 0,774 je historický resubstituční výsledek. Pro interpretaci potřebujeme také podpory tříd, precision, recall a informaci o neklasifikovaných pixelech.'),
S('Co se při porovnání mění', (57,57), 'Pořadí metod může změnit testovací vzorek, trénovací vzorek i náhodná inicializace. Opakované běhy zachycují jinou variabilitu než nové nezávislé datasety.|Párové porovnání používá stejné testovací případy pro oba modely. Reportuj rozdělení rozdílů a protokol, nikoli jen dvě nejlepší hodnoty.'),
S('McNemarův test', (58,59), 'Test pro dvě metody na stejných případech využívá pouze neshodné výsledky: b případů správně jen metodou A, c správně jen metodou B.|Příklad b=14, c=5 dává s korekcí 64/19≈3,368. V podkladu nedosahuje hranice 3,841 pro asymptotický test na hladině 0,05. Malý počet neshod je vhodné řešit přesným binomickým testem.', [r'\chi^2=\frac{(|b-c|-1)^2}{b+c}'], comment='Nedostatek průkazu rozdílu není průkaz stejného výkonu. Nezávislost testovacích jednotek je stále důležitý předpoklad.'),
S('Více metod na více úlohách', (60,61), 'Friedmanův test používá pořadí K metod v N blocích, typicky datasetech. Shody dostanou průměrné pořadí; test zkoumá souhrnnou nulovou hypotézu.|Zamítnutí samo neurčí, které dvojice se liší. Následné testy potřebují kontrolu násobného porovnávání. Číselný příklad v podkladu je historická demonstrace, ne nové benchmarkové tvrzení.', [r'\chi_F^2=\frac{12N}{K(K+1)}\sum_j\bar r_j^2-3N(K+1)'])
]

COURSES[8] = [
S('Strukturní a syntaktické rozpoznávání', (1,2), 'Rozpoznávání obrazců VIII · Michal Haindl · podklady 2023–2024.|Místo jediného příznakového vektoru popíšeme části objektu a jejich vztahy. Pracovat budeme se slovy, stromy, gramatikami, automaty a grafy.', diagram='grammar'),
S('Objekt jako části a vztahy', (3,8), 'Strukturní rozpoznávání porovnává relační popis objektu s modely. Syntaktické rozpoznávání zkoumá, zda popis dokáže vygenerovat gramatika určité třídy.|Řetězec zachytí pořadí, strom hierarchii a graf obecnější vztahy. Před vlastní analýzou musíme části detekovat a pojmenovat.', diagram='tree'),
S('Volba primitiv', (9,16), 'Primitivum je základní jednotka v rámci zvoleného popisu, ne absolutně nedělitelný fyzický objekt. Má být rozpoznatelné, stabilní a dostatečné k popisu sledovaných tvarů.|Freemanův řetězový kód zaznamenává směry obrysu. Porovnání slov vyžaduje ošetřit výchozí bod, orientaci, šum a případné chybějící části.'),
S('Gramatika a jazyk', (17,25), 'Gramatika obsahuje terminální symboly T, neterminály N, pravidla P a počáteční symbol S. Jazyk tvoří všechna terminální slova odvoditelná ze S.|Pravidlo přepisuje levou stranu na pravou v přípustném kontextu. Odvození poskytuje kromě přijetí také strukturu popisu.', [r'G=(N,T,P,S)',r'L(G)=\{w\in T^*:S\Rightarrow^*w\}'], comment='Příklad „the dog barks furiously“ se rozkládá na jmennou a slovesnou frázi. Při přepisu sjednocujeme překlepy, které v původní ukázce zaměňovaly názvy symbolů.'),
S('Relace nejsou jen hrany obrázku', (26,32), 'Relace je podmnožina kartézského součinu. Binární relace může být reflexivní, symetrická, tranzitivní nebo antisymetrická; tyto vlastnosti jsou nezávislé požadavky.|Ekvivalence rozděluje množinu na třídy. Kompatibilita nemusí být tranzitivní. Obecnou n-ární relaci nelze vždy bezeztrátově nahradit pouhou sadou jejích párových projekcí.', [r'R\subseteq M_1\times\cdots\times M_n']),
S('Slova a prázdné slovo', (33,36), 'Abeceda je konečná množina symbolů. Prázdné slovo značíme ε; prázdný jazyk ∅ neobsahuje ani toto slovo. Σ* obsahuje všechna konečná slova včetně ε.|Jazyk aⁿbⁿ generuje pravidlo S→aSb spolu se S→ε. Texturové gramatiky místo posloupností mohou používat sousednosti primitiv.', [r'L=\{a^nb^n:n\ge0\}',r'S\to aSb\mid\varepsilon'], diagram='grammar'),
S('Chomského hierarchie', (37,42), 'Regulární gramatiky odpovídají konečným automatům. Bezkontextové gramatiky mají na levé straně jediný neterminál a zachytí například vnořování.|Kontextové gramatiky mají obecně větší sílu, neomezené ještě větší. Vyšší popisná síla přináší složitější analýzu; u obecných gramatik není rozhodování členství obecně rozhodnutelné.', [r'L_3\subsetneq L_2\subsetneq L_1\subsetneq L_0']),
S('Stochastická a fuzzy pravidla', (43,46), 'Stochastická gramatika přiřazuje pravděpodobnosti alternativním přepisům. Pro daný levý symbol se jejich pravděpodobnosti sčítají na jedna.|To samo nemusí zaručit, že odvození skončí s pravděpodobností jedna. Fuzzy váhy vyjadřují míru příslušnosti a nepodléhají stejnému normalizačnímu požadavku.'),
S('Pravděpodobnost odvození', (47,49), 'V ukázce S→1A, A→0B s pravděpodobností 0,8 a B→0 s pravděpodobností 0,3 vznikne slovo 100 s pravděpodobností 0,24.|Pokud má slovo více odvození, jeho pravděpodobnost je součet jejich pravděpodobností. Cyklus s faktorem 0,56 zde vede ke geometrické řadě s celkovou hmotností jedna.', [r'P(100)=1\cdot0.8\cdot0.3=0.24',r'\sum_{n=0}^{\infty}0.44\cdot0.56^n=1']),
S('Grafové gramatiky a síla primitiv', (50,52), 'Grafová pravidla přepisují část grafu a určují její napojení do okolí. U řetězce je toto vložení jednodušší, protože má lineární pořadí.|Složitější primitiva mohou zjednodušit gramatiku, ale přesunou obtížnost do detekce a segmentace. Obě části systému je třeba hodnotit společně.'),
S('Konečný automat', (53,54), 'Deterministický automat má aktuální stav a pro každý symbol jednoznačný další stav. Přijme slovo, když po jeho přečtení skončí v přijímajícím stavu.|Nedeterministický automat dovoluje více pokračování. Převod na deterministický zachová jazyk, ale může výrazně zvýšit počet stavů. Regulární gramatika a konečný automat popisují stejnou rodinu jazyků.', [r'A=(Q,\Sigma,\delta,q_0,F)'], diagram='automaton'),
S('Analýza shora a zdola', (55,64), 'Top-down parser začíná v S a zkouší rozvinout popis ke vstupu. Bottom-up parser začíná ve vstupu a redukuje části podle pravidel směrem k S.|Výraz a+b×c má respektovat násobení uvnitř sčítání. Neúspěšné slepé větvení není samo o sobě obecný rozhodovací algoritmus pro všechny gramatiky; používáme parser vhodný pro danou třídu.', diagram='tree'),
S('Chyby a učení gramatiky', (65,68), 'Chybově opravná analýza připouští vložení, smazání či záměnu symbolu a hledá přípustný popis s nízkou cenou změn.|Konečná trénovací sada neurčuje jediný nekonečný jazyk. Potřebujeme induktivní předpoklad, omezení rodiny gramatik nebo negativní příklady. Přesné zapamatování vzorků není zobecnění.'),
S('Crespi-Reghizzi: využití známé struktury', (69,77), 'Ukázková metoda předpokládá, že známe závorkování nebo odvozovací strukturu trénovacích slov. Nejdříve vytvoří pravidla pro nejhlouběji uzavřené podřetězce a postupuje k větším celkům.|Podřetězec a se stane samostatným pravidlem; a následované b lze reprezentovat dalším neterminálem. Sjednocení pravidel z více stromů umožní opakování i nové kombinace, které je potřeba kontrolovat.'),
S('Evansova indukční metoda', (78,89), 'Z opakujících se podřetězců sestavíme dílčí gramatiky. Poté odstraňujeme duplicitní pravidla a sjednocujeme vhodné neterminály.|Historický příklad končí pravidly S→cA nebo S→bbA a A→aA nebo A→b. Výsledek tedy obsahuje c aⁿ b i bb aⁿ b pro n≥0; generuje více než původních sedm ukázek.', [r'S\to cA\mid bbA',r'A\to aA\mid b'], comment='V zápisu používáme b místo h, aby byly dvojice a/b čitelné. Důležitý je vzor odvození a kontrola jazyka, nikoli jména neterminálů.'),
S('Porovnávání grafů', (90,90), 'Izomorfismus hledá bijekci vrcholů zachovávající hrany v obou směrech. Podgrafový izomorfismus hledá odpovídající část většího grafu.|U reálných dat bývá potřebné přibližné porovnání s cenou změny vrcholu či hrany. Požadavek přesné shody může být příliš citlivý na chybu detekce primitiv.')
]

COURSES[9] = [
S('Neuronové sítě jako model', (1,3), 'Rozpoznávání obrazců IX · Michal Haindl · podklady 2023–2024.|Od biologické inspirace přejdeme k matematickému neuronu, aktivacím, grafu sítě, zpětné vazbě a reprezentaci. Historické soudy podkladu neprezentujeme jako dnešní měření.', diagram='neuron'),
S('Biologická inspirace a její meze', (4,13), 'Biologický neuron, synapse a výpočetní jednotka nejsou zaměnitelné objekty. Umělá síť je účelový model; její úspěch nevyžaduje věrnou simulaci celého mozku.|Podklad připomíná vývoj od logických neuronů přes perceptron k rekurentním a hlubokým sítím. Staré energetické a kapacitní odhady závisí na definici operace a způsobu měření; nepřebíráme je jako aktuální srovnání.'),
S('Symbolické systémy a naučené reprezentace', (14,22), 'Expertní systém pracuje s explicitními znalostmi a pravidly. Síť přizpůsobuje parametry podle dat. Rozdíl je v reprezentaci a procesu učení, ne v jednoduchém dělení na logiku a inteligenci.|Historické příklady zahrnují ART, LVQ, asociativní paměti, klasifikaci i optimalizaci. Symbolické a numerické postupy lze kombinovat.'),
S('Vážený součet, bias a aktivace', (23,27), 'Neuron vypočte afinní kombinaci vstupů a poté aktivační funkci. Bias posune přechod; pokud používáme práh θ, odpovídá biasu b=−θ.|Konstantní vstup 1 s vahou b umožní bias zahrnout do rozšířeného vektoru. Pečlivě odlišujeme znaménka prahu a biasu.', [r'z=w^\top x+b',r'y=f(z)'], diagram='neuron'),
S('Práh, sigmoid a tanh', (28,32), 'Skoková funkce dává tvrdé rozhodnutí, sigmoid hladký přechod mezi 0 a 1. Tanh je symetrický kolem nuly.|Saturace malých derivací může ztížit přenos gradientu. Hodnota sigmoidového výstupu není automaticky kalibrovaná pravděpodobnost.', [r'\sigma(z)=\frac1{1+e^{-z}}',r'\sigma^{\prime}(z)=\sigma(z)(1-\sigma(z))',r'\tanh^{\prime}(z)=1-\tanh^2(z)']),
S('ReLU a její varianty', (33,36), 'ReLU zachová kladnou část a zápornou vynuluje. Leaky ReLU ponechá v záporné části malý sklon; parametrická varianta se tento sklon učí.|Nespojitá derivace v nule neznamená, že funkce je nespojitá. Hard tanh výstup omezí mezi −1 a 1.', [r'\mathrm{ReLU}(z)=\max(0,z)',r'\mathrm{LeakyReLU}(z)=\max(\alpha z,z)',r'0<\alpha<1']),
S('Hladké aktivační funkce', (37,44), 'Swish násobí vstup sigmoidovou bránou, GELU vstup distribuční funkcí standardní normály. Softplus je hladká aproximace kladné části.|CELU, SELU, Mish a TanhExp mění růst a saturaci. Srovnání má používat stejný protokol učení a uvést volné parametry; samotná hladkost nezaručí nejlepší výkon.', [r'\mathrm{Swish}(z)=z\sigma(\beta z)',r'\mathrm{GELU}(z)=z\Phi(z)',r'\mathrm{softplus}(z)=\log(1+e^z)']),
S('Další aktivace a meze závěrů', (45,51), 'Polynomiální, sinusové a erf aktivace přinášejí odlišnou spektrální a růstovou charakteristiku. Volba souvisí s úlohou i normalizací vstupu.|Podklad odkazuje na experiment s modelováním BRDF z roku 2023. Jeho výsledek není univerzální důkaz převahy jedné aktivace. Teoretické limity nekonečné šířky či hloubky vyžadují konkrétní předpoklady.'),
S('Síť je orientovaný výpočetní graf', (52,57), 'Hrany přenášejí vážené signály, uzel je sčítá a aplikuje vlastní transformaci. Rozvětvení kopíruje signál do více navazujících výpočtů.|Nelineární vrstvy umožňují složité mapování. Čistě lineární vrstvy bez nelinearity lze složit do jediné lineární transformace.', [r'h^{(l+1)}=f_l(W_lh^{(l)}+b_l)'], diagram='network'),
S('Zpětná vazba a stabilita', (58,60), 'Rekurentní síť vrací minulý stav do dalšího kroku. U lineárního skalárního příkladu hₜ=a hₜ₋₁+uₜ bez vstupu stav násobíme v každém kroku a.|Podmínka |a|<1 znamená odeznívání počátečního stavu. Při |a|=1 může stav přetrvávat nebo oscilovat, takže tvrzení o automatické divergenci na celé hranici by bylo příliš silné.', [r'h_t=a^th_0+\sum_{j=1}^{t}a^{t-j}u_j']),
S('Architektura určuje povolené vazby', (61,70), 'Dopředná síť nemá cykly, rekurentní má stav nebo zpětné vazby. Plně propojené a lokální vrstvy používají jiné sdílení parametrů a předpoklady.|DenseNet využívá dopředná propojení mezi vrstvami; nepropojuje libovolně všechny vrstvy v obou směrech. Siamská síť používá sdílený převod dvou vstupů a následné porovnání.', diagram='network'),
S('Generátor a diskriminátor', (71,72), 'GAN společně trénuje generátor syntetických dat a diskriminátor odlišující jejich rozdělení od reálných dat. Obě části se mění, takže se mění i učení protistrany.|Vizuálně přesvědčivý výstup není důkazem stejného rozdělení ani vědeckým měřením. Režimy kolapsu a kvalita generování vyžadují vlastní hodnocení.'),
S('Otevřené problémy a volba kapacity', (73,80), 'Přenos mimo trénovací rozdělení, předsudky, zapomínání, vysvětlitelnost a náklady jsou samostatné osy hodnocení. Číselná tvrzení o energii či úspěšnosti z původních slajdů jsou dobově podmíněná.|Síť lze zmenšovat prořezáváním nebo postupně rozšiřovat. Více neuronů automaticky neznamená ani lepší výkon, ani nevyhnutelné selhání. Kapacitu, regularizaci a učení ověřujeme validací.'),
S('Co má reprezentace zachovat', (81,83), 'Užitečná reprezentace přibližuje relevantně podobné případy a odděluje různé třídy. Předem známou symetrii můžeme vložit do architektury nebo podpořit augmentací.|Symetrická matice vah sama nezaručuje rotační invarianci. Musíme přesně popsat transformaci vstupu a požadovanou invarianci nebo ekvivarianci výstupu.', [r'f(Tx)=f(x)\quad\text{(invariance)}',r'f(Tx)=T^{\prime}f(x)\quad\text{(ekvivariance)}'])
]

COURSES[11] = [
S('Genetické algoritmy', (1,2), 'Rozpoznávání obrazců XI · Michal Haindl · podklady 2023–2024.|Populační hledání kombinuje hodnocení, výběr a variaci. Projdeme kódování, operátory a příklady shlukování, segmentace a výběru příznaků.', diagram='evolution'),
S('Inspirace není záruka optimality', (3,8), 'Genetický algoritmus udržuje populaci kandidátních řešení. Výběr upřednostňuje lepší skóre, křížení kombinuje části a mutace vytváří další varianty.|Nepotřebuje derivaci, ale potřebuje mnoho vyhodnocení a rozumné kódování. Umí opustit některá lokální optima; globální optimum v konečném běhu nezaručuje.'),
S('Kódování a počáteční populace', (9,10), 'Chromozom může být bitový řetězec, vektor hodnot, permutace nebo strom. Povolené operátory musí zachovat význam a přípustnost řešení.|Počáteční populace může kombinovat náhodné i známé dobré kandidáty. Větší populace přináší více rozmanitosti za cenu času a paměti.'),
S('Fitness a pravděpodobnost výběru', (11,15), 'Fitness je účelové hodnocení kandidáta, nikoli přirozená pravda o jeho kvalitě. Záleží na tom, zda maximalizujeme užitek nebo minimalizujeme cenu.|Při Boltzmannově výběru vyšší teplota zplošťuje rozdělení, nižší soustředí výběr na nejlepší. Pro numerickou stabilitu lze od všech fitness odečíst jejich maximum.', [r'P(i)=\frac{e^{f_i/T}}{\sum_je^{f_j/T}}']),
S('Jednobodové a vícebodové křížení', (16,25), 'Jednobodové křížení vezme prefix jednoho rodiče a suffix druhého. Dvoubodové vymění úsek, uniformní používá masku po jednotlivých pozicích.|U permutací prosté prohození úseku může vytvořit opakované a chybějící prvky. Speciální varianty, tři rodiče nebo omezení místa řezu mění distribuční vlastnosti hledání.', diagram='crossover'),
S('Mutace a další operátory', (26,29), 'Bitová mutace převrátí vybraný bit. Záměna dvou pozic nebo obrácení úseku má jiný účinek a může lépe odpovídat kódování.|Pravděpodobnost 1/d na bit vede k jednomu změněnému bitu v průměru, nikoli v každém potomkovi. Běh ukončujeme podle rozpočtu a stagnace; stagnace nedokazuje optimum.', [r'E[\#\text{mutací}]=dp']),
S('Biologická odbočka je historický kontext', (30,32), 'Původní přednáška uvádí molekulární hodiny a genetickou variabilitu jako biologickou motivaci. Tyto populační a časové odhady nejsou parametry optimalizačního algoritmu.|Pro výpočetní metodu stačí definovat reprezentaci, dědičnost a operátory. Dobová biologická čísla nepřebíráme jako nově ověřená tvrzení.'),
S('Požadavky na reprezentaci', (33,37), 'Úplnost znamená možnost zakódovat každé hledané řešení, přípustnost opačný směr: každý vytvářený kód má dávat platné řešení. Redundance může komplikovat hledání.|Generace tvoří vyhodnocení, výběr, křížení, mutace a nové vyhodnocení. Elitismus může uchovat nejlepšího kandidáta, ale příliš silný výběr omezí rozmanitost.', diagram='evolution'),
S('Genetické programování', (38,39), 'Místo parametrů hledáme program nebo výrazový strom. Křížení zaměňuje kompatibilní podstromy, mutace mění uzly nebo strukturu.|Syntaktická správnost sama nezaručuje bezpečné vyhodnocení. Potřebujeme například ošetřit dělení nulou a penalizovat neúčelný růst stromů.'),
S('Kódování shlukování', (40,46), 'Chromozom může obsahovat značku shluku každého objektu nebo souřadnice reprezentantů. Permutace jmen shluků představuje stejné rozdělení, a proto vytváří redundanci.|Sloučení a rozštěpení shluků jsou účelové operátory. U reprezentantů lze křížit celé středy a mutovat jejich souřadnice. Cílová funkce má odpovídat zvolené vzdálenosti.', [r'J=\sum_i\min_kd(x_i,\mu_k)']),
S('Kontextová důvěra v segmentaci', (47,49), 'Lokální skóre hodnotí vlastnosti oblasti; kompatibilita hodnotí, zda spolu sousední interpretace dávají smysl. Fitness pak skládá lokální a vztahové informace.|Takové skóre nemusí být normalizovaná pravděpodobnost. Nelze jej automaticky číst jako procentní jistotu správnosti celé segmentace.', [r'u_i=\frac1{|N_i|}\sum_{j\in N_i}r(y_i,y_j)c_j(y_j)',r'F(y)=\sum_i c_i(y_i)u_i']),
S('Genetická segmentace krok za krokem', (50,56), 'Nejdříve vytvoříme primární oblasti a jejich graf sousednosti. Chromozom určí interpretaci oblastí. Pro každou hypotézu aktualizujeme vztahy a vypočteme fitness.|Po výběru, křížení a mutaci hodnotíme novou generaci. Nejlepší nalezená interpretace závisí na připravených oblastech, pravidlech i rozpočtu; algoritmus neopraví chybějící základní informaci.'),
S('Míč na trávníku', (57,61), 'Didaktický příklad kombinuje kruhovitost pro míč, zelenost pro trávník a vztah „míč uvnitř trávníku“. Různé řetězce značek vyjadřují různé hypotézy.|Čísla fitness v podkladu patří konstruované ukázce. Nejde o měření detektoru na reálném testovacím souboru.', diagram='regions'),
S('Výběr příznaků bitovou maskou', (62,62), 'Jednička znamená použitý příznak a nula vyřazený. Fitness může spojit validační výkon s penalizací počtu nebo ceny příznaků.|Hledání opakovaně zkouší mnoho masek. Finální výkon proto hodnotíme na vnějším testu; interní vítězné skóre je ovlivněné výběrem.', [r'F(J)=\mathrm{score}_{val}(J)-\lambda|J|']),
S('Historické experimenty s kůrou stromů', (63,69), 'Podklad porovnává příznaky 2D/3D SCAR na sadách BarkNet, BarkTex a dalších texturových datech. Uvádí například 23 tříd BarkNet a tabulky precision a sensitivity jednotlivých druhů.|Jde o převzaté výsledky historického výzkumu, ne o nový experiment GRAFIT. Přesné dílčí tabulky a protokoly jsou v odkázaném PDF a článku Remeš–Haindl (2019). Rozdílné sady ani verze protokolu neslučujeme do jednoho pořadí.', comment='Při čtení souhrnného procenta zkontroluj podporu vzácných tříd, dělení dat a zda obrázky stejného stromu nesdílejí trénink a test. Hezká tabulka sama nedokazuje přenos na nové stromy.')
]

COURSES[12] = [
S('SVM a kombinování klasifikátorů', (1,2), 'Rozpoznávání obrazců XII · Michal Haindl · podklady 2023–2024.|Od geometrie oddělující nadroviny odvodíme tvrdý a měkký okraj, duál, jádra a vícetřídé rozhodování. Nakonec spojíme více klasifikátorů.', diagram='margin'),
S('Proč maximalizovat okraj', (3,13), 'SVM hledá oddělení s velkou vzdáleností nejbližších trénovacích bodů od hranice. Velký okraj souvisí s kontrolou kapacity, nikoli s automatickou zárukou úspěchu na libovolných datech.|Klasické jádrové metody mohou vyžadovat kvadratickou paměť na Gramovu matici. Výpočetní cena závisí na řešiči, řídkosti i datech; není obecně jen lineární ve velikosti tréninku.', diagram='margin'),
S('Nadrovina a geometrická vzdálenost', (14,16), 'Rozhodovací funkce je g(x)=wᵀx+b. Znaménko určí binární třídu; velikost g sama závisí na škále parametrů.|Podepsaná vzdálenost dělí hodnotu funkcí normou w. V kanonickém zápisu jsou podpůrné nadroviny g=±1. Celková šířka pásu je 2/‖w‖.', [r'd(x,H)=\frac{w^\top x+b}{\|w\|}',r'y_i(w^\top x_i+b)\ge1']),
S('Primal: tvrdý okraj', (17,18), 'U lineárně separovatelných dat minimalizujeme polovinu čtverce normy při podmínce správného kanonického oddělení všech bodů.|Podpůrné vektory leží na aktivních omezeních. Při neseparovatelnosti tato úloha nemá přípustné řešení.', [r'\min_{w,b}\frac12\|w\|^2',r'y_i(w^\top x_i+b)\ge1\quad\forall i']),
S('Lagrangeovy multiplikátory a duál', (19,22), 'Každé omezení dostane nezáporný multiplikátor αᵢ. Stacionarita dává váhový vektor jako kombinaci trénovacích vzorků a nulový součet αᵢyᵢ.|Duál maximalizuje konkávní kvadratickou funkci. Nulové αᵢ přispívat nemusí; aktivní multiplikátory určují výsledný model.', [r'w=\sum_i\alpha_i y_ix_i',r'\sum_i\alpha_iy_i=0,\quad\alpha_i\ge0',r'\max_\alpha\ \sum_i\alpha_i-\frac12\sum_{i,j}\alpha_i\alpha_jy_iy_jx_i^\top x_j']),
S('Co zaručuje konvexita', (23,26), 'U konvexní úlohy jsou za splněných předpokladů KKT podmínky podmínkami optimality. Nemusíme hledat mezi odlišnými lokálními minimy jako u obecné neuronové sítě.|Jedinečnost w neznamená obecně jedinečnost všech multiplikátorů nebo biasu v každé degenerované variantě. Klasifikace využije součet jen přes podpůrné vektory.', [r'g(x)=\sum_{i\in SV}\alpha_i y_i x_i^\top x+b']),
S('Měkký okraj a proměnné ξ', (27,30), 'Neseparovatelná data dovolují porušení okraje. ξ=0 splňuje kanonické omezení, 0<ξ<1 leží správně uvnitř pásu a ξ>1 může znamenat chybné znaménko.|Penalizujeme součet porušení, nikoli přímo počet chyb. Velké C zvyšuje cenu porušení; malé dává větší prostor regularizaci.', [r'\min\ \frac12\|w\|^2+C\sum_i\xi_i',r'y_i(w^\top x_i+b)\ge1-\xi_i,\quad\xi_i\ge0']),
S('Měkký okraj v duálu', (31,35), 'Duální multiplikátory nyní leží mezi 0 a C. U bodů s 0<αᵢ<C je ξᵢ=0 a bod leží na okraji; z těchto bodů lze určit bias.|Pokud takové body chybějí, bias se určuje z přípustného intervalu nebo podle řešiče. Zvyšování C neudělá neseparovatelná data separovatelnými.', [r'0\le\alpha_i\le C',r'b=y_i-\sum_j\alpha_jy_jK(x_j,x_i)',r'0<\alpha_i<C']),
S('Více než dvě třídy', (36,39), 'One-vs-rest učí K binárních modelů, one-vs-one K(K−1)/2. Jejich skóre a hlasování vyžadují pravidlo řešení shod.|Existují i společné vícetřídé optimalizační formulace. SVM proto není principiálně omezeno na dvě třídy; binární odvození je výchozí stavební kámen.'),
S('Jádrový trik', (40,45), 'Skalární součin ve vhodném prostoru příznaků nahradíme jádrem K(x,z). Aby šlo o platné reálné jádro, musí být symetrické a jeho Gramovy matice pozitivně semidefinitní.|Lineární, polynomiální a Gaussovo RBF jádro představují různé podobnosti. RBF používá čtverec vzdálenosti x−z, nikoli čtverec skalárního součinu.', [r'K(x,z)=\langle\phi(x),\phi(z)\rangle',r'K_{RBF}(x,z)=e^{-\gamma\|x-z\|^2},\quad\gamma>0',r'g(x)=\sum_{i\in SV}\alpha_i y_iK(x_i,x)+b'], comment='Redakčně opravujeme nejasný zápis původního RBF vzorce. Sigmoidové tanh jádro není platné pro libovolné parametry.'),
S('Výběr jádra a regularizace', (46,50), 'Společně ladíme C, parametry jádra i předzpracování. Volba musí proběhnout uvnitř validačního procesu, konečný test zůstává stranou.|SVM kombinuje chybu na tréninku s kontrolou složitosti. Ani dobré trénovací skóre ani velký okraj samy neověřují odolnost vůči změně rozdělení.', diagram='split'),
S('Co jednotlivé klasifikátory vracejí', (51,53), 'Některé modely vracejí jen třídu, jiné pořadí nebo vektor skóre. Slučovat můžeme pouze výstupy s jasně sjednoceným významem a pořadím tříd.|Raw SVM skóre není posteriorní pravděpodobnost. Kalibrace i váhy kombinace se učí na vhodně oddělených datech.'),
S('Hlasování a Borda', (54,57), 'Většinové hlasování počítá vítězné třídy dílčích modelů. Borda sčítá pořadí každé třídy a vybírá nejnižší součet.|Vazby a váhy musí být předem definované. Pro tři žebříčky [1,5,4,2,3], [5,1,3,2,4], [5,3,1,4,2] jsou součty pořadí tříd [6,13,10,12,4], vítězí tedy třída 5.', [r'R(k)=\sum_{j=1}^{m}r_j(k)',r'\widehat y=\arg\min_kR(k)']),
S('Kombinace skóre', (58,58), 'Průměr, minimum a maximum mají různý význam. Maximum zvýrazní optimistický model, minimum vyžaduje souhlas a průměr vyrovnává rozdíly.|Průměr kalibrovaných pravděpodobností může být užitečný ensemble. Prostý součin nebo jiná „Bayesovská“ kombinace vyžaduje model závislostí; nelze automaticky násobit posteriory a opakovaně započítat prior.', [r'\bar p_k=\frac1m\sum_jp_j(k)'])
]
